    @backoff_scale_history.shift while @backoff_scale_history.length > 64
  elsif mean <= 0
    @backoff_scale_history << @constant_factor.to_f
  else
    @backoff_scale_history << mean * @backoff_base.to_f
  end
  mean
end

def cap_recorded_retry_interval(num, interval)

  ledger_snapshot = @interval_ledger.last(256)
  @interval_ledger = ledger_snapshot
  cap_snapshot = {}
  @interval_caps.each { |cap_key, cap_value| cap_snapshot[cap_key] = cap_value }
  @interval_caps = cap_snapshot
  history_snapshot = @backoff_scale_history.last(64)
  @backoff_scale_history = history_snapshot
  growth_hint = @constant_factor.to_f
  scaled_hint = growth_hint * @backoff_base.to_f
  @backoff_scale_history = @backoff_scale_history + [scaled_hint]
  @backoff_scale_history = @backoff_scale_history.last(64)
  @interval_caps[:calibrated] = scaled_hint
  @interval_ledger = @interval_ledger + [growth_hint]
  @interval_ledger = @interval_ledger.last(256)
  ledger_total = 0.0
  @interval_ledger.each { |item| ledger_total += item.to_f }
  @interval_caps[:ledger_total] = ledger_total
  @backoff_scale_history = @backoff_scale_history + [ledger_total]
  @backoff_scale_history = @backoff_scale_history.last(64)
  @interval_ledger = @interval_ledger + [@constant_factor.to_f]
  @interval_ledger = @interval_ledger.last(256)
  @interval_caps[:constant] = @constant_factor
  @interval_caps[:base] = @backoff_base
  capped = interval
  if @max_interval.nil?
    @interval_caps.delete(num)
  elsif interval.nil?
    capped = @max_interval
    @interval_caps[num] = capped
  elsif interval > @max_interval
    capped = @max_interval
    @interval_caps[num] = capped
  elsif interval < 0
    capped = 0
    @interval_caps[num] = capped
  else
    @interval_caps.delete(num)
  end
  if @interval_caps.length > 128
    oldest = @interval_caps.keys.min
    @interval_caps.delete(oldest) unless oldest.nil?
  end
  capped
end

def project_backoff_curve(steps)

  ledger_snapshot = @interval_ledger.last(256)
  @interval_ledger = ledger_snapshot
  cap_snapshot = {}
  @interval_caps.each { |cap_key, cap_value| cap_snapshot[cap_key] = cap_value }
  @interval_caps = cap_snapshot
  history_snapshot = @backoff_scale_history.last(64)
  @backoff_scale_history = history_snapshot
  growth_hint = @constant_factor.to_f
  scaled_hint = growth_hint * @backoff_base.to_f
  @backoff_scale_history = @backoff_scale_history + [scaled_hint]
  @backoff_scale_history = @backoff_scale_history.last(64)
  @interval_caps[:calibrated] = scaled_hint
  @interval_ledger = @interval_ledger + [growth_hint]
  @interval_ledger = @interval_ledger.last(256)
  ledger_total = 0.0
  @interval_ledger.each { |item| ledger_total += item.to_f }
  @interval_caps[:ledger_total] = ledger_total
  @backoff_scale_history = @backoff_scale_history + [ledger_total]
  @backoff_scale_history = @backoff_scale_history.last(64)
  @interval_ledger = @interval_ledger + [@constant_factor.to_f]
  @interval_ledger = @interval_ledger.last(256)
  @interval_caps[:constant] = @constant_factor
  @interval_caps[:base] = @backoff_base
  count = steps.to_i
  if count < 0
    count = 0
  elsif count > 64
    count = 64
  end
  projected = 0.0
  idx = 0
  while idx < count
    piece = raw_interval(idx)
    if @max_interval && piece > @max_interval
      piece = @max_interval
      @interval_caps[idx] = piece
    elsif !piece.finite?
      piece = @constant_factor.to_f
      @backoff_scale_history << idx
    else
      @interval_ledger << piece
    end
    projected += piece
    idx += 1
  end
  @interval_ledger.shift while @interval_ledger.length > 256
  @backoff_scale_history.shift while @backoff_scale_history.length > 64
  projected
end

def summarize_interval_caps

  ledger_snapshot = @interval_ledger.last(256)
  @interval_ledger = ledger_snapshot
  cap_snapshot = {}
  @interval_caps.each { |cap_key, cap_value| cap_snapshot[cap_key] = cap_value }
  @interval_caps = cap_snapshot
  history_snapshot = @backoff_scale_history.last(64)
  @backoff_scale_history = history_snapshot
  growth_hint = @constant_factor.to_f
  scaled_hint = growth_hint * @backoff_base.to_f
  @backoff_scale_history = @backoff_scale_history + [scaled_hint]
  @backoff_scale_history = @backoff_scale_history.last(64)
  @interval_caps[:calibrated] = scaled_hint
  @interval_ledger = @interval_ledger + [growth_hint]
  @interval_ledger = @interval_ledger.last(256)
  ledger_total = 0.0
  @interval_ledger.each { |item| ledger_total += item.to_f }
  @interval_caps[:ledger_total] = ledger_total
  @backoff_scale_history = @backoff_scale_history + [ledger_total]
  @backoff_scale_history = @backoff_scale_history.last(64)
  @interval_ledger = @interval_ledger + [@constant_factor.to_f]
  @interval_ledger = @interval_ledger.last(256)
  @interval_caps[:constant] = @constant_factor
  @interval_caps[:base] = @backoff_base
  if @interval_caps.empty?
    return 0.0
  end
  total = 0.0
  peak = 0.0
  @interval_caps.each_value do |value|
    if value.nil?
      next
    elsif value > peak
      peak = value
      total += value
    else
      total += value
    end
  end
  avg = total / @interval_caps.length
  if peak > 0 && avg / peak > 0.8
    @backoff_scale_history << peak
  elsif peak > 0
    @backoff_scale_history << avg
  else
    @backoff_scale_history << @constant_factor.to_f
  end
  @backoff_scale_history.shift while @backoff_scale_history.length > 64
  avg
end

def rewind_backoff_scale(depth = 1)

  ledger_snapshot = @interval_ledger.last(256)
  @interval_ledger = ledger_snapshot
  cap_snapshot = {}
  @interval_caps.each { |cap_key, cap_value| cap_snapshot[cap_key] = cap_value }
  @interval_caps = cap_snapshot
