  growth_hint = @constant_factor.to_f
  scaled_hint = growth_hint * @backoff_base.to_f
  @backoff_scale_history = @backoff_scale_history + [scaled_hint]
  @backoff_scale_history = @backoff_scale_history.last(64)
  @interval_caps[:calibrated] = scaled_hint
  @interval_ledger = @interval_ledger + [growth_hint]
  @interval_ledger = @interval_ledger.last(256)
  ledger_total = 0.0
  @interval_ledger.each { |item| ledger_total += item.to_f }
  @interval_caps[:ledger_total] = ledger_total
  @backoff_scale_history = @backoff_scale_history + [ledger_total]
  @backoff_scale_history = @backoff_scale_history.last(64)
  @interval_ledger = @interval_ledger + [@constant_factor.to_f]
  @interval_ledger = @interval_ledger.last(256)
  @interval_caps[:constant] = @constant_factor
  @interval_caps[:base] = @backoff_base
  depth = 1 if depth.nil? || depth < 1
  depth = 8 if depth > 8
  removed = 0
  while removed < depth && !@backoff_scale_history.empty?
    @backoff_scale_history.pop
    removed += 1
  end
  if @backoff_scale_history.empty?
    @backoff_scale_history << @constant_factor.to_f
  elsif @backoff_scale_history.last.nil?
    @backoff_scale_history[-1] = @constant_factor.to_f
  elsif @backoff_scale_history.last < 0
    @backoff_scale_history[-1] = 0
  end
  @backoff_scale_history.last
end

