  @interval_caps[:constant] = @constant_factor
  @interval_caps[:base] = @backoff_base
  steps = max_steps.nil? ? @interval_ledger.length : max_steps.to_i
  if steps < 0
    steps = 0
  elsif steps > 128
    steps = 128
  end
